const body = $json.body || $json;
const tenantSlug = (body.tenantSlug || 'wondernails').trim();
const message = (body.message || '').trim();
const history = Array.isArray(body.history) ? body.history.slice(-6) : [];
const sessionId = body.sessionId || null;

if (!message) return [];

return [{ json: { tenantSlug, message, history, sessionId } }];

const rows = $('Get Tenant + Services').all().map(i => i.json);
const cfg = rows[0] || {};
const ctx = $('Parse Chat Payload').item.json;
const services = rows.filter(r => r.service_name).map(r => r.service_name + ' ($' + r.price + ' MXN, ' + r.duration + 'min)').join(', ');

const systemPrompt = 'Eres ' + (cfg.bot_name || 'Wonder') + ', el asistente virtual de ' + (cfg.tenant_name || 'WonderNails') + '. Tono: ' + (cfg.tone || 'amigable, cercano y profesional') + '. Responde en español, en 1-3 oraciones, sin markdown.\n\nServicios disponibles: ' + (services || 'manicure, pedicure, uñas gel, acrílico') + '\n\nSi el usuario quiere agendar una cita, invítalo amablemente a hacerlo desde el botón \'Reservar\' del sitio (no intentes agendar la cita tú mismo en esta conversación). Si preguntan algo fuera de tu alcance como salón de belleza, dilo con honestidad y ofrece ayuda con lo que sí sabes.';

const historyMessages = (ctx.history || []).map(h => ({ role: h.role === 'assistant' ? 'assistant' : 'user', content: String(h.content || '').slice(0, 500) }));

return [{
  json: {
    tenantSlug: ctx.tenantSlug,
    sessionId: ctx.sessionId,
    systemPrompt,
    userMessage: ctx.message,
    historyMessages
  }
}];

const aiResp = $('Call Ollama Cloud').item.json;
const ctx = $('Build Ollama Prompt').item.json;
const reply = aiResp?.choices?.[0]?.message?.content?.trim() || 'Hola, soy Wonder 🐾 En este momento no puedo responder, ¿puedes intentar de nuevo en un momento?';

return [{ json: { reply, tenantSlug: ctx.tenantSlug, sessionId: ctx.sessionId } }];
